css:
/* Social & Communication Collection: CSS-only hover animations
   Each animation designed via Socratic method:
   1. What real-world thing? 2. What motion? 3. Which elements? 4. Same at rest? */

.si-anim svg { overflow: visible; }

/* ===================================================================
   1. MESSAGE-CIRCLE: A chat bubble. New message arrives.
   Motion: bubble scales up with a pop, like a notification appearing.
   Elements: whole bubble. Single shape, unified motion.
   =================================================================== */
.si-icon-cell:hover .mbt6e2 .sc-bubble,
.icon-card:hover .mbt6e2 .sc-bubble {
  animation: agcrgo 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: 12px 18px;
}
.si-icon-cell:hover .mbt6e2 svg,
.icon-card:hover .mbt6e2 svg {
  filter: drop-shadow(0 0 3px rgba(99, 102, 241, 0.25));
}

/* ===================================================================
   2. HEART: A beating organ. Double-pump rhythm.
   Motion: two quick scale pulses mimicking systole/diastole.
   Elements: whole heart. Biological unity.
   =================================================================== */
.si-icon-cell:hover .vwu29v .sc-heart,
.icon-card:hover .vwu29v .sc-heart {
  animation: uftwta 0.65s ease forwards;
  transform-origin: 12px 12px;
}
.si-icon-cell:hover .vwu29v svg,
.icon-card:hover .vwu29v svg {
  filter: drop-shadow(0 0 4px rgba(239, 68, 68, 0.3));
}

/* ===================================================================
   3. SHARE: A network broadcast. Signal radiates outward.
   Motion: nodes pulse OUTWARD staggered (broadcast ripple), links stay.
   Elements: 3 circles individually (staggered), lines static.
   =================================================================== */
.si-icon-cell:hover .ygzoc0 .sc-node-1,
.icon-card:hover .ygzoc0 .sc-node-1 {
  animation: pco6sh 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: 18px 5px;
}
.si-icon-cell:hover .ygzoc0 .sc-node-2,
.icon-card:hover .ygzoc0 .sc-node-2 {
  animation: pco6sh 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) 0.08s forwards;
  transform-origin: 6px 12px;
}
.si-icon-cell:hover .ygzoc0 .sc-node-3,
.icon-card:hover .ygzoc0 .sc-node-3 {
  animation: pco6sh 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) 0.16s forwards;
  transform-origin: 18px 19px;
}
.si-icon-cell:hover .ygzoc0 svg,
.icon-card:hover .ygzoc0 svg {
  filter: drop-shadow(0 0 3px rgba(99, 102, 241, 0.25));
}

/* ===================================================================
   4. USERS: A group of people greeting. Second person arrives.
   Motion: primary head nods, secondary user slides in from right.
   Elements: head (nod), user-2/3 (slide in).
   =================================================================== */
.si-icon-cell:hover .aqh89i .sc-head,
.icon-card:hover .aqh89i .sc-head {
  animation: s3dt66 0.5s ease forwards;
  transform-origin: 9px 7px;
}
.si-icon-cell:hover .aqh89i .sc-user-2,
.icon-card:hover .aqh89i .sc-user-2 {
  animation: wfbqfr 0.5s ease 0.1s forwards;
}
.si-icon-cell:hover .aqh89i .sc-user-3,
.icon-card:hover .aqh89i .sc-user-3 {
  animation: wfbqfr 0.5s ease 0.15s forwards;
}
.si-icon-cell:hover .aqh89i svg,
.icon-card:hover .aqh89i svg {
  filter: drop-shadow(0 0 3px rgba(96, 165, 250, 0.2));
}

/* ===================================================================
   5. PHONE: A ringing telephone. Vibrating on a surface.
   Motion: rapid oscillating rotation (ring vibration pattern).
   Elements: whole phone. Physical vibration is unified.
   =================================================================== */
.si-icon-cell:hover .xgitsv svg,
.icon-card:hover .xgitsv svg {
  animation: fksezv 0.5s ease forwards;
  transform-origin: center;
  filter: drop-shadow(0 0 3px rgba(34, 197, 94, 0.3));
}

/* ===================================================================
   6. MAIL: An envelope being opened. Flap lifts up.
   Motion: the V-shaped flap rotates upward (opens), envelope stays.
   Elements: flap (rotates), envelope body (static).
   =================================================================== */
.si-icon-cell:hover .awoobl .sc-flap,
.icon-card:hover .awoobl .sc-flap {
  animation: t5rxtz 0.5s ease forwards;
  transform-origin: 12px 7px;
}
.si-icon-cell:hover .awoobl svg,
.icon-card:hover .awoobl svg {
  filter: drop-shadow(0 0 3px rgba(59, 130, 246, 0.25));
}

/* ===================================================================
   7. SEND: Paper plane being thrown. Launches diagonally.
   Motion: whole plane shoots up-right then returns (throw arc).
   Elements: whole SVG. Plane is one unified projectile.
   =================================================================== */
.si-icon-cell:hover .ezf012 svg,
.icon-card:hover .ezf012 svg {
  animation: jt8cpc 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: center;
  filter: drop-shadow(0 0 3px rgba(99, 102, 241, 0.25));
}

/* ===================================================================
   8. AT-SIGN: An @ mention. Drawing attention.
   Motion: inner circle spins 360, outer ring stays (focus on the @).
   Elements: inner circle (spin), outer path (static).
   =================================================================== */
.si-icon-cell:hover .qm85pi .sc-at-outer,
.icon-card:hover .qm85pi .sc-at-outer {
  animation: vyv0z4 0.5s ease forwards;
  transform-origin: 12px 12px;
}
.si-icon-cell:hover .qm85pi .sc-at-inner,
.icon-card:hover .qm85pi .sc-at-inner {
  animation: pco6sh 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) 0.1s forwards;
  transform-origin: 12px 12px;
}
.si-icon-cell:hover .qm85pi svg,
.icon-card:hover .qm85pi svg {
  filter: drop-shadow(0 0 3px rgba(139, 92, 246, 0.25));
}

/* ===================================================================
   9. THUMBS-UP: Raising your thumb in approval.
   Motion: whole hand tilts backward (raising gesture) then settles.
   Elements: whole SVG. Hand + divider are one physical unit.
   =================================================================== */
.si-icon-cell:hover .x8bpi8 svg,
.icon-card:hover .x8bpi8 svg {
  animation: n841jb 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: center bottom;
  filter: drop-shadow(0 0 3px rgba(34, 197, 94, 0.25));
}

/* ===================================================================
   10. BOOKMARK: Placing a ribbon bookmark into a book.
   Motion: flag slides down (drops into page) then bounces up slightly.
   Elements: whole SVG. Single flag shape.
   =================================================================== */
.si-icon-cell:hover .rnt2va svg,
.icon-card:hover .rnt2va svg {
  animation: jvsrq6 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: center top;
  filter: drop-shadow(0 0 3px rgba(251, 191, 36, 0.25));
}

/* ===================================================================
   11. SMILE: A happy face reacting. Eyes squint, face wiggles.
   Motion: face tilts side to side (joy wiggle), mouth scales wider.
   Elements: face (tilt), mouth (scale wider).
   =================================================================== */
.si-icon-cell:hover .vcmv3k .sc-face,
.icon-card:hover .vcmv3k .sc-face {
  animation: popifi 0.6s ease forwards;
  transform-origin: center;
}
.si-icon-cell:hover .vcmv3k .sc-mouth,
.icon-card:hover .vcmv3k .sc-mouth {
  animation: q3av6u 0.5s ease 0.1s forwards;
  transform-origin: 12px 14px;
}
.si-icon-cell:hover .vcmv3k svg,
.icon-card:hover .vcmv3k svg {
  filter: drop-shadow(0 0 3px rgba(251, 191, 36, 0.25));
}

/* ===================================================================
   12. REPLY: Sending a message back. Arrow curves backwards.
   Motion: whole icon slides left (going back direction) with bounce.
   Elements: whole SVG. Arrow and curve are one gesture.
   =================================================================== */
.si-icon-cell:hover .rtix6c svg,
.icon-card:hover .rtix6c svg {
  animation: wzevne 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  filter: drop-shadow(0 0 3px rgba(96, 165, 250, 0.25));
}

/* ===================================================================
   13. FORWARD: Passing a message on. Arrow curves forward.
   Motion: whole icon slides right (forward direction) with bounce.
   Elements: whole SVG. Arrow and curve are one gesture.
   =================================================================== */
.si-icon-cell:hover .d2kv7j svg,
.icon-card:hover .d2kv7j svg {
  animation: ae14xh 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  filter: drop-shadow(0 0 3px rgba(96, 165, 250, 0.25));
}

/* ===================================================================
   14. VIDEO: A camera starting to record. Lens focuses.
   Motion: lens (triangle) pulses like REC indicator, body stays still.
   Elements: lens (pulse), body (static).
   =================================================================== */
.si-icon-cell:hover .mnem8c .sc-lens,
.icon-card:hover .mnem8c .sc-lens {
  animation: vv3zvz 0.6s ease forwards;
  transform-origin: 19px 12px;
}
.si-icon-cell:hover .mnem8c svg,
.icon-card:hover .mnem8c svg {
  filter: drop-shadow(0 0 4px rgba(239, 68, 68, 0.3));
}

/* ===================================================================
   15. MIC: Microphone picking up audio. Capsule vibrates with sound.
   Motion: capsule vibrates vertically (sound), wave arc pulses.
   Elements: capsule (vibrate), wave path (opacity pulse).
   =================================================================== */
.si-icon-cell:hover .h87r6w .sc-capsule,
.icon-card:hover .h87r6w .sc-capsule {
  animation: gzpc46 0.5s ease forwards;
  transform-origin: 12px 8px;
}
.si-icon-cell:hover .h87r6w .sc-wave,
.icon-card:hover .h87r6w .sc-wave {
  animation: dmfp5a 0.5s ease 0.1s forwards;
  transform-origin: 12px 12px;
}
.si-icon-cell:hover .h87r6w svg,
.icon-card:hover .h87r6w svg {
  filter: drop-shadow(0 0 3px rgba(34, 197, 94, 0.25));
}

/* ===================================================================
   16. BELL-RING: Notification bell ringing. Pendulum swing.
   Motion: bell swings like a pendulum from top, waves pulse outward.
   Elements: bell body (pendulum swing), wave lines (opacity pulse).
   =================================================================== */
.si-icon-cell:hover .p0j8ft .sc-bell,
.icon-card:hover .p0j8ft .sc-bell {
  animation: o9wofv 0.6s ease forwards;
  transform-origin: 12px 2px;
}
.si-icon-cell:hover .p0j8ft .sc-wave,
.icon-card:hover .p0j8ft .sc-wave {
  animation: dmfp5a 0.4s ease 0.15s forwards;
}
.si-icon-cell:hover .p0j8ft svg,
.icon-card:hover .p0j8ft svg {
  filter: drop-shadow(0 0 3px rgba(192, 132, 252, 0.25));
}

/* ===================================================================
   17. LINK: Chain links. Testing the connection.
   Motion: two halves tug in opposite diagonal directions then snap.
   Elements: chain-1 (up-right), chain-2 (down-left). Opposing pull.
   =================================================================== */
.si-icon-cell:hover .t6943d .sc-chain-1,
.icon-card:hover .t6943d .sc-chain-1 {
  animation: e9j93c 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}
.si-icon-cell:hover .t6943d .sc-chain-2,
.icon-card:hover .t6943d .sc-chain-2 {
  animation: fkhkaj 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}
.si-icon-cell:hover .t6943d svg,
.icon-card:hover .t6943d svg {
  filter: drop-shadow(0 0 3px rgba(96, 165, 250, 0.25));
}

/* ===================================================================
   18. MEGAPHONE: Shouting an announcement. Amplified vibration.
   Motion: horn shakes with increasing amplitude (building volume).
   Elements: horn (shake), handle stays. Sound direction: rightward.
   =================================================================== */
.si-icon-cell:hover .gu2ji5 .sc-horn,
.icon-card:hover .gu2ji5 .sc-horn {
  animation: aezi1j 0.5s ease forwards;
  transform-origin: 5px 10px;
}
.si-icon-cell:hover .gu2ji5 svg,
.icon-card:hover .gu2ji5 svg {
  filter: drop-shadow(0 0 3px rgba(249, 115, 22, 0.25));
}

/* ===================================================================
   19. USER-PLUS: Adding a new friend. Plus icon pops in.
   Motion: plus lines scale up from center (appear), user body stays.
   Elements: plus lines (pop scale), user silhouette (static).
   =================================================================== */
.si-icon-cell:hover .dewisd .sc-plus,
.icon-card:hover .dewisd .sc-plus {
  animation: i9x7mz 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: 19px 11px;
}
.si-icon-cell:hover .dewisd svg,
.icon-card:hover .dewisd svg {
  filter: drop-shadow(0 0 3px rgba(34, 197, 94, 0.25));
}

/* ===================================================================
   20. CONTACT-ROUND: Opening a contact card. Card tilts up to read.
   Motion: card rotates slightly (picked up to read), avatar pulses.
   Elements: card (tilt), avatar circle (pulse).
   =================================================================== */
.si-icon-cell:hover .r6au04 .sc-card,
.icon-card:hover .r6au04 .sc-card {
  animation: an2jl0 0.5s ease forwards;
  transform-origin: 12px 22px;
}
.si-icon-cell:hover .r6au04 .sc-avatar,
.icon-card:hover .r6au04 .sc-avatar {
  animation: pco6sh 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) 0.15s forwards;
  transform-origin: 12px 12px;
}
.si-icon-cell:hover .r6au04 svg,
.icon-card:hover .r6au04 svg {
  filter: drop-shadow(0 0 3px rgba(99, 102, 241, 0.25));
}

/* ===================== KEYFRAMES ===================== */
/* Every keyframe is purpose-built. No generic reuse where stories differ. */

/* Message arrive: chat bubble drops in and wobbles like a notification */
@keyframes agcrgo {
  0%   { transform: translateY(-6px) rotate(-8deg); }
  35%  { transform: translateY(2px) rotate(4deg); }
  55%  { transform: translateY(-1px) rotate(-2deg); }
  75%  { transform: translateY(0.5px) rotate(1deg); }
  100% { transform: translateY(0) rotate(0deg); }
}

/* Heartbeat: two-pump cardiac rhythm with organic twist */
@keyframes uftwta {
  0%   { transform: scale(1) rotate(0deg); }
  14%  { transform: scale(1.28) rotate(-4deg); }
  28%  { transform: scale(0.95) rotate(2deg); }
  42%  { transform: scale(1.2) rotate(-2deg); }
  56%  { transform: scale(1) rotate(0deg); }
  100% { transform: scale(1) rotate(0deg); }
}

/* Node pop: individual network node expanding */
@keyframes pco6sh {
  0%   { transform: scale(1); }
  40%  { transform: scale(1.45); }
  70%  { transform: scale(0.9); }
  100% { transform: scale(1); }
}

/* Head nod: person tilting head forward */
@keyframes s3dt66 {
  0%   { transform: translateY(0) scale(1); }
  30%  { transform: translateY(-2px) scale(1.06); }
  60%  { transform: translateY(1px) scale(0.98); }
  100% { transform: translateY(0) scale(1); }
}

/* Arrive: second person sliding in from right */
@keyframes wfbqfr {
  0%   { transform: translateX(3px); opacity: 0.5; }
  50%  { transform: translateX(-1px); opacity: 1; }
  100% { transform: translateX(0); opacity: 1; }
}

/* Ring vibrate: phone buzzing rapidly */
@keyframes fksezv {
  0%   { transform: rotate(0deg) translateX(0); }
  8%   { transform: rotate(10deg) translateX(1px); }
  16%  { transform: rotate(-8deg) translateX(-1px); }
  24%  { transform: rotate(10deg) translateX(1px); }
  32%  { transform: rotate(-8deg) translateX(-1px); }
  40%  { transform: rotate(6deg); }
  50%  { transform: rotate(-4deg); }
  60%  { transform: rotate(2deg); }
  70%  { transform: rotate(-1deg); }
  100% { transform: rotate(0deg) translateX(0); }
}

/* Flap open: envelope V lifts up and settles */
@keyframes t5rxtz {
  0%   { transform: rotateX(0deg); }
  45%  { transform: rotateX(-40deg); }
  70%  { transform: rotateX(5deg); }
  100% { transform: rotateX(0deg); }
}

/* Launch: projectile arc (up-right then return) */
@keyframes jt8cpc {
  0%   { transform: translate(0, 0) rotate(0deg); }
  35%  { transform: translate(5px, -5px) rotate(-8deg); }
  60%  { transform: translate(-1px, 1px) rotate(2deg); }
  100% { transform: translate(0, 0) rotate(0deg); }
}

/* Mention ping: @ wiggle like someone tagging you */
@keyframes vyv0z4 {
  0%   { transform: rotate(0deg); }
  15%  { transform: rotate(8deg); }
  30%  { transform: rotate(-6deg); }
  45%  { transform: rotate(5deg); }
  60%  { transform: rotate(-3deg); }
  75%  { transform: rotate(1deg); }
  100% { transform: rotate(0deg); }
}

/* Raise thumb: tilting hand backward in approval */
@keyframes n841jb {
  0%   { transform: rotate(0deg) translateY(0); }
  35%  { transform: rotate(-12deg) translateY(-3px); }
  60%  { transform: rotate(3deg) translateY(1px); }
  100% { transform: rotate(0deg) translateY(0); }
}

/* Bookmark place: ribbon dropping into page */
@keyframes jvsrq6 {
  0%   { transform: translateY(-4px) scaleY(0.92); }
  45%  { transform: translateY(2px) scaleY(1.06); }
  70%  { transform: translateY(-1px) scaleY(0.98); }
  100% { transform: translateY(0) scaleY(1); }
}

/* Joy tilt: happy face wiggling side to side */
@keyframes popifi {
  0%   { transform: rotate(0deg); }
  15%  { transform: rotate(6deg); }
  30%  { transform: rotate(-5deg); }
  45%  { transform: rotate(4deg); }
  60%  { transform: rotate(-2deg); }
  75%  { transform: rotate(1deg); }
  100% { transform: rotate(0deg); }
}

/* Grin: mouth stretching wider */
@keyframes q3av6u {
  0%   { transform: scaleX(1) scaleY(1); }
  40%  { transform: scaleX(1.25) scaleY(1.15); }
  70%  { transform: scaleX(0.95) scaleY(0.95); }
  100% { transform: scaleX(1) scaleY(1); }
}

/* Swipe left: reply gesture */
@keyframes wzevne {
  0%   { transform: translateX(0); }
  35%  { transform: translateX(-5px); }
  65%  { transform: translateX(1.5px); }
  100% { transform: translateX(0); }
}

/* Swipe right: forward gesture */
@keyframes ae14xh {
  0%   { transform: translateX(0); }
  35%  { transform: translateX(5px); }
  65%  { transform: translateX(-1.5px); }
  100% { transform: translateX(0); }
}

/* Rec blink: recording indicator double-pulse */
@keyframes vv3zvz {
  0%   { transform: scale(1); opacity: 1; }
  20%  { transform: scale(1.3); opacity: 0.7; }
  40%  { transform: scale(1); opacity: 1; }
  60%  { transform: scale(1.2); opacity: 0.8; }
  80%  { transform: scale(1); opacity: 1; }
  100% { transform: scale(1); opacity: 1; }
}

/* Audio vibrate: mic capsule picking up sound */
@keyframes gzpc46 {
  0%   { transform: scaleY(1); }
  12%  { transform: scaleY(1.08); }
  24%  { transform: scaleY(0.94); }
  36%  { transform: scaleY(1.1); }
  48%  { transform: scaleY(0.96); }
  60%  { transform: scaleY(1.06); }
  72%  { transform: scaleY(0.98); }
  100% { transform: scaleY(1); }
}

/* Wave spread: sound wave expanding */
@keyframes dmfp5a {
  0%   { transform: scale(1); opacity: 1; }
  40%  { transform: scale(1.12); opacity: 0.6; }
  70%  { transform: scale(1.03); opacity: 0.85; }
  100% { transform: scale(1); opacity: 1; }
}

/* Pendulum: bell swinging from top mount */
@keyframes o9wofv {
  0%   { transform: rotate(0deg); }
  12%  { transform: rotate(16deg); }
  28%  { transform: rotate(-14deg); }
  42%  { transform: rotate(10deg); }
  56%  { transform: rotate(-7deg); }
  70%  { transform: rotate(4deg); }
  84%  { transform: rotate(-2deg); }
  100% { transform: rotate(0deg); }
}

/* Pull up-right: chain link testing tension */
@keyframes e9j93c {
  0%   { transform: translate(0, 0); }
  35%  { transform: translate(2.5px, -2.5px); }
  65%  { transform: translate(-0.5px, 0.5px); }
  100% { transform: translate(0, 0); }
}

/* Pull down-left: opposite chain link */
@keyframes fkhkaj {
  0%   { transform: translate(0, 0); }
  35%  { transform: translate(-2.5px, 2.5px); }
  65%  { transform: translate(0.5px, -0.5px); }
  100% { transform: translate(0, 0); }
}

/* Broadcast shake: megaphone amplifying sound */
@keyframes aezi1j {
  0%   { transform: rotate(0deg); }
  10%  { transform: rotate(2deg); }
  20%  { transform: rotate(-3deg); }
  30%  { transform: rotate(5deg); }
  40%  { transform: rotate(-6deg); }
  50%  { transform: rotate(7deg); }
  60%  { transform: rotate(-5deg); }
  70%  { transform: rotate(3deg); }
  80%  { transform: rotate(-1deg); }
  100% { transform: rotate(0deg); }
}

/* Plus pop: add friend icon appearing */
@keyframes i9x7mz {
  0%   { transform: scale(1) rotate(0deg); }
  30%  { transform: scale(1.5) rotate(90deg); }
  60%  { transform: scale(0.85) rotate(0deg); }
  100% { transform: scale(1) rotate(0deg); }
}

/* Card tilt: picking up a contact card to read */
@keyframes an2jl0 {
  0%   { transform: rotate(0deg) translateY(0); }
  40%  { transform: rotate(-4deg) translateY(-2px); }
  70%  { transform: rotate(1deg) translateY(0.5px); }
  100% { transform: rotate(0deg) translateY(0); }
}

/* ===================================================================
   ICONS 21-50: HOVER RULES
   =================================================================== */

/* 21. MESSAGE-SQUARE: chat box wobbles like typing indicator */
.si-icon-cell:hover .r8oqr5 .sc-box,
.icon-card:hover .r8oqr5 .sc-box {
  animation: agcrgo 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: 12px 20px;
}
.si-icon-cell:hover .r8oqr5 svg,
.icon-card:hover .r8oqr5 svg {
  filter: drop-shadow(0 0 3px rgba(99, 102, 241, 0.25));
}

/* 22. INBOX: mail drops into the tray */
.si-icon-cell:hover .c5p6s9 .sc-shelf,
.icon-card:hover .c5p6s9 .sc-shelf {
  animation: r8xn7q 0.5s ease forwards;
  transform-origin: 12px 12px;
}
.si-icon-cell:hover .c5p6s9 svg,
.icon-card:hover .c5p6s9 svg {
  filter: drop-shadow(0 0 3px rgba(59, 130, 246, 0.25));
}

/* 23. THUMBS-DOWN: whole hand tilts downward (disapproval) */
.si-icon-cell:hover .trqyth svg,
.icon-card:hover .trqyth svg {
  animation: uitf5x 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: center top;
  filter: drop-shadow(0 0 3px rgba(239, 68, 68, 0.25));
}

/* 24. STAR: twinkle with rotation */
.si-icon-cell:hover .dqlmd4 .sc-star,
.icon-card:hover .dqlmd4 .sc-star {
  animation: g6jm1t 0.6s ease forwards;
  transform-origin: 12px 12px;
}
