/* Inbox: mail item dropping into shelf */
@keyframes r8xn7q {
  0%   { transform: translateY(-5px); opacity: 0.6; }
  50%  { transform: translateY(1px); opacity: 1; }
  75%  { transform: translateY(-1px); }
  100% { transform: translateY(0); opacity: 1; }
}

/* Lower thumb: disapproval gesture tilt */
@keyframes uitf5x {
  0%   { transform: rotate(0deg) translateY(0); }
  35%  { transform: rotate(12deg) translateY(3px); }
  60%  { transform: rotate(-3deg) translateY(-1px); }
  100% { transform: rotate(0deg) translateY(0); }
}

/* Twinkle: star sparkle rotation */
@keyframes g6jm1t {
  0%   { transform: rotate(0deg); opacity: 1; }
  25%  { transform: rotate(18deg); opacity: 0.7; }
  50%  { transform: rotate(-5deg); opacity: 1; }
  75%  { transform: rotate(8deg); opacity: 0.85; }
  100% { transform: rotate(0deg); opacity: 1; }
}

/* Flutter: flag waving in wind */
@keyframes osrt8f {
  0%   { transform: skewX(0deg); }
  15%  { transform: skewX(3deg); }
  30%  { transform: skewX(-2deg); }
  45%  { transform: skewX(2deg); }
  60%  { transform: skewX(-1deg); }
  75%  { transform: skewX(0.5deg); }
  100% { transform: skewX(0deg); }
}

/* Look around: eye tracking */
@keyframes vu5163 {
  0%   { transform: translateX(0); }
  25%  { transform: translateX(2px); }
  50%  { transform: translateX(0); }
  75%  { transform: translateX(-2px); }
  100% { transform: translateX(0); }
}

/* Blink: eyelid quick blink */
@keyframes b08fkr {
  0%   { transform: scaleY(1); }
  40%  { transform: scaleY(0.1); }
  60%  { transform: scaleY(1); }
  100% { transform: scaleY(1); }
}

/* Globe spin on vertical axis */
@keyframes qqfwv0 {
  0%   { transform: scaleX(1); }
  25%  { transform: scaleX(0.3); }
  50%  { transform: scaleX(-1); }
  75%  { transform: scaleX(0.3); }
  100% { transform: scaleX(1); }
}

/* Shoot up: upload gesture */
@keyframes whhwcd {
  0%   { transform: translateY(0); }
  35%  { transform: translateY(-4px); }
  65%  { transform: translateY(1px); }
  100% { transform: translateY(0); }
}

/* Shoot down: download gesture */
@keyframes xt2h4h {
  0%   { transform: translateY(0); }
  35%  { transform: translateY(4px); }
  65%  { transform: translateY(-1px); }
  100% { transform: translateY(0); }
}

/* Check sweep: verification mark appearing */
@keyframes btmqdd {
  0%   { transform: scale(0.5) rotate(-20deg); opacity: 0.3; }
  50%  { transform: scale(1.3) rotate(5deg); opacity: 1; }
  75%  { transform: scale(0.9) rotate(-2deg); }
  100% { transform: scale(1) rotate(0deg); opacity: 1; }
}

